import React, { useState, useEffect } from 'react';
import './RiverDashboard.css';

// ==========================================
// CONFIGURATION
// ==========================================
const DATA_BASE_URL = '.';
const CSV_FILE_NAME = 'forecast_output_20251216_124441.csv';
const TXT_FILE_NAME = 'lime_short_sentences_and_labels.txt';

// --- Premium SVG Icons ---
const WaterIcon = () => (
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2.69l5.66 5.66a8 8 0 1 1-11.31 0z"/></svg>
);
const ChartIcon = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="20" x2="18" y2="10"></line><line x1="12" y1="20" x2="12" y2="4"></line><line x1="6" y1="20" x2="6" y2="14"></line></svg>
);
const BrainIcon = () => (
  <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M9.5 2A2.5 2.5 0 0 1 12 4.5v15a2.5 2.5 0 0 1-4.96.44 2.5 2.5 0 0 1-2.96-3.08 3 3 0 0 1-.34-5.58 2.5 2.5 0 0 1 1.32-4.24 2.5 2.5 0 0 1 1.98-3A2.5 2.5 0 0 1 9.5 2Z"></path><path d="M14.5 2A2.5 2.5 0 0 0 12 4.5v15a2.5 2.5 0 0 0 4.96.44 2.5 2.5 0 0 0 2.96-3.08 3 3 0 0 0 .34-5.58 2.5 2.5 0 0 0-1.32-4.24 2.5 2.5 0 0 0-1.98-3A2.5 2.5 0 0 0 14.5 2Z"></path></svg>
);
const CheckIcon = () => (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>
);
const AlertIcon = () => (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"></path><line x1="12" y1="9" x2="12" y2="13"></line><line x1="12" y1="17" x2="12.01" y2="17"></line></svg>
);

const RiverDashboard = () => {
  const [forecastData, setForecastData] = useState([]);
  const [limeDetails, setLimeDetails] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  const parseCSV = (csvText) => {
    const lines = csvText.split('\n').filter(line => line.trim() !== '');
    if (lines.length < 2) return []; 
    const headers = lines[0].split(',').map(h => h.trim());
    const data = [];
    for (let i = 1; i < lines.length; i++) {
        const values = lines[i].split(',');
        if (values.length === headers.length) {
            let rowObject = {};
            for (let j = 0; j < headers.length; j++) {
                rowObject[headers[j]] = values[j].trim();
            }
            data.push(rowObject);
        }
    }
    return data;
  };

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      setError(null);
      try {
        const csvResponse = await fetch(`${DATA_BASE_URL}/${CSV_FILE_NAME}`);
        if (!csvResponse.ok) throw new Error('Failed to load Forecast CSV');
        const csvText = await csvResponse.text();
        setForecastData(parseCSV(csvText));

        const txtResponse = await fetch(`${DATA_BASE_URL}/${TXT_FILE_NAME}`);
        if (!txtResponse.ok) throw new Error('Failed to load LIME Text');
        const txtText = await txtResponse.text();
        setLimeDetails(txtText.split('\n').filter(line => line.trim() !== ''));

      } catch (err) {
        console.error("Error:", err);
        setError("Unable to retrieve river data. Please check connection.");
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, []);

  if (isLoading) return <div className="loading-screen"><div className="spinner"></div>Loading Analytics Engine...</div>;
  if (error) return <div className="error-screen">{error}</div>;

  const tableHeaders = forecastData.length > 0 ? Object.keys(forecastData[0]) : [];

  return (
    <div className="dashboard-container">
      <header className="main-header">
        <div className="header-content">
            <div className="logo-wrapper">
                <div className="logo-icon"><WaterIcon /></div>
                <div className="logo-text">
                    <h1>Periyar Monitor</h1>
                    <span className="subtitle">Advanced Analytics System</span>
                </div>
            </div>
            <div className="status-badge">
                <span className="dot pulse"></span> Live Monitoring
            </div>
        </div>
      </header>

      <main className="dashboard-content">
        
        {/* --- Hero Section --- */}
        <section className="hero-section">
            <div className="hero-card">
                <div className="hero-content">
                    <span className="hero-label">Current Water Level</span>
                    <div className="hero-value-group">
                        <h1 className="hero-value">1.41</h1>
                        <span className="hero-unit">Litres</span>
                    </div>
                    <div className="hero-details">
                        <div className="detail-item">
                            <span className="label">Date</span>
                            <span className="value">8/08/24</span>
                        </div>
                        <div className="detail-item">
                            <span className="label">Status</span>
                            <span className="value status-ok">Normal Flow</span>
                        </div>
                    </div>
                </div>
                {/* Decorative background circle */}
                <div className="hero-decoration"></div>
            </div>
        </section>

        {/* --- Forecast Table Section --- */}
        <section className="data-section">
            <div className="glass-card table-card">
                <div className="card-header">
                    <div className="icon-box"><ChartIcon /></div>
                    <h3>6-Hour Forecast Prediction</h3>
                </div>
                <div className="table-responsive">
                    <table className="premium-table">
                        <thead>
                            <tr>
                                {tableHeaders.map((header, i) => (
                                    <th key={i}>{header.replace(/_/g, ' ')}</th>
                                ))}
                            </tr>
                        </thead>
                        <tbody>
                            {forecastData.map((row, i) => (
                                <tr key={i}>
                                    {tableHeaders.map((h, j) => (
                                        <td key={j}>{row[h]}</td>
                                    ))}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </section>

        {/* --- LIME Analysis Section (Centered & Padded) --- */}
        <section className="analysis-section">
            <div className="glass-card lime-card">
                <div className="card-header center-header">
                    <div className="icon-box large-icon"><BrainIcon /></div>
                    <h3>AI Causality Analysis</h3>
                    <p className="section-desc">Key factors influencing the river level predictions</p>
                </div>
                
                <div className="insights-container">
                    {limeDetails.map((line, index) => {
                        const isGreen = line.toUpperCase().includes('[GREEN]');
                        const isOrange = line.toUpperCase().includes('[ORANGE]');
                        const cleanLine = line.replace(/\[GREEN\]|\[ORANGE\]/gi, '').trim();
                        
                        let className = "insight-card";
                        let Icon = ChartIcon; 

                        if (isGreen) {
                            className += " safe-insight";
                            Icon = CheckIcon;
                        } else if (isOrange) {
                            className += " warning-insight";
                            Icon = AlertIcon;
                        }

                        // Splitting time (H+1) from message
                        const parts = cleanLine.split(':');
                        const time = parts[0];
                        const message = parts.slice(1).join(':').trim();

                        return (
                            <div key={index} className={className}>
                                <div className="insight-left">
                                    <div className="insight-icon-circle"><Icon /></div>
                                    <span className="insight-time">{time}</span>
                                </div>
                                <div className="insight-content">
                                    <p>{message || cleanLine}</p>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>
        </section>

      </main>
    </div>
  );
};

export default RiverDashboard;
